{

    internal InnerDataAutomationProjectImageStandardGenerativeFieldFactory GenerativeFieldFactory { get; set; }

    internal InnerDataAutomationProjectImageStandardExtractionFactory ExtractionFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardOutputConfiguration Create()
    {
        var imageStandardOutputConfigurationResult = CreateImageStandardOutputConfiguration();
        factoryAction?.Invoke(imageStandardOutputConfigurationResult);

        return imageStandardOutputConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardOutputConfiguration CreateImageStandardOutputConfiguration()
    {
        var imageStandardOutputConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardOutputConfiguration();

        return imageStandardOutputConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardOutputConfiguration result)
    {
        base.CreateChildren(result);

        result.GenerativeField ??= GenerativeFieldFactory?.Build();
        result.Extraction ??= ExtractionFactory?.Build();
    }

} // End Of Class

